// The Markdown under results/: one page per schema, and the matrix of every schema run so far.

const CHECKS = [
  ['model', 'Mapping'],
  ['insert', 'Insert'],
  ['read', 'Read back'],
  ['update', 'Update'],
  ['relations', 'Relations'],
  ['delete', 'Delete'],
]

export function renderSchema(name, plan, results, { schemaHref = `../../schemas/${name}/schema.prisma`, about = [] } = {}) {
  const lines = [
    `# ${name}`,
    '',
    `[schema.prisma](${schemaHref}) · ${plan.dialect} · ${plan.models.length} models.`,
    ...about,
    'Generated by `node run.mjs` (see [README](../README.md)); do not edit.',
    '',
    `| ORM | ${CHECKS.map(([, t]) => t).join(' | ')} | Tables (DDL) |`,
    `| --- | ${CHECKS.map(() => '--:').join(' | ')} | --- |`,
  ]
  for (const r of results) {
    if (r.generatorError) {
      lines.push(`| ${r.orm} | ❌ the generator failed on this schema |${CHECKS.slice(1).map(() => '').join(' |')} |`)
      continue
    }
    if (r.notGenerated) {
      lines.push(`| ${r.orm} | not generated: hekireki leaves it out of this schema |${CHECKS.slice(1).map(() => '').join(' |')} |`)
      continue
    }
    if (r.fatal) {
      lines.push(`| ${r.orm} | ${CHECKS.map(() => '—').join(' | ')} | — |`)
      continue
    }
    const cells = CHECKS.map(([c]) => cell(r.crud.counts[c]))
    lines.push(`| ${r.orm} | ${cells.join(' | ')} | ${ddlCell(r.ddl)} |`)
  }
  for (const r of results.filter((x) => !x.notGenerated)) {
    lines.push('', `## ${r.orm}`, '')
    if (r.generatorError) {
      lines.push(`hekireki-${r.orm} failed on the schema:`, '', '```text', r.generatorError, '```')
      continue
    }
    if (r.fatal) {
      lines.push('The harness did not run:', '', '```text', r.fatal, '```')
      continue
    }
    if (r.crud.findings.length === 0) lines.push('Every row went in, came back as written, joined and went out.')
    else {
      for (const f of r.crud.findings) {
        lines.push(`- **${f.model}** (${f.check}): ${f.text}`)
        if (f.detail) lines.push('', '  ```text', ...oneLine(f.detail).map((l) => `  ${l}`), '  ```')
      }
    }
    lines.push('')
    if (r.ddl?.na) lines.push(`**Tables:** ${r.ddl.na}`)
    else if (r.ddl?.error) lines.push('**Tables:** the ORM could not create them:', '', '```text', r.ddl.error, '```')
    else if (r.ddl?.diff === '') lines.push('**Tables:** the ORM creates exactly the tables Prisma does (`prisma migrate diff` is empty).')
    else if (r.ddl)
      lines.push(
        '**Tables:** what `prisma migrate diff` would run to turn the tables the ORM creates into the ones Prisma does:',
        '',
        '<details><summary>' + summarizeDiff(r.ddl.diff) + '</summary>',
        '',
        '```sql',
        r.ddl.diff,
        '```',
        '',
        '</details>',
      )
  }
  return lines.join('\n') + '\n'
}

export function renderIndex(
  all,
  {
    title = 'Results',
    intro = 'Each cell: the runtime checks that passed (insert, read back, update, relations, delete, per model) and whether the tables the ORM creates on its own are the ones Prisma creates. Generated by `node run.mjs`; do not edit.',
    columns = [],
  } = {},
) {
  const orms = [...new Set(all.flatMap((s) => s.orms.map((o) => o.orm)))]
  const lines = [
    `# ${title}`,
    '',
    intro,
    '',
    `| Schema | ${[...columns.map((c) => c.title), ...orms].join(' | ')} |`,
    `| --- | ${[...columns, ...orms].map(() => '---').join(' | ')} |`,
  ]
  for (const s of all.sort((a, b) => a.name.localeCompare(b.name))) {
    const cells = orms.map((orm) => {
      const o = s.orms.find((x) => x.orm === orm)
      if (!o) return ''
      if (o.generatorError) return '❌ generator failed'
      if (o.notGenerated) return 'not generated'
      if (o.fatal) return '❌ did not run'
      const total = Object.values(o.checks).reduce((n, c) => n + c.total, 0)
      const ok = Object.values(o.checks).reduce((n, c) => n + c.ok, 0)
      const mark = ok === total ? '✅' : '⚠️'
      const ddl = { same: 'tables ✅', differs: 'tables ≠', error: 'tables ❌', na: 'no tables' }[o.ddl] ?? ''
      return `${mark} ${ok}/${total} · ${ddl}`
    })
    lines.push(`| [${s.name}](${s.name}.md) | ${[...columns.map((c) => c.value(s)), ...cells].join(' | ')} |`)
  }
  return lines.join('\n') + '\n'
}

function cell({ ok, total }) {
  if (total === 0) return '—'
  return ok === total ? `✅ ${ok}/${total}` : `⚠️ ${ok}/${total}`
}

function ddlCell(ddl) {
  if (!ddl || ddl.na) return '—'
  if (ddl.error) return '❌ not created'
  if (ddl.diff === '') return '✅ same'
  return `≠ ${summarizeDiff(ddl.diff)}`
}

// "24 statements: 9 AlterTable, 5 DropForeignKey, ...", by the `-- Kind` headers Prisma writes.
function summarizeDiff(sql) {
  const code = sql
    .split('\n')
    .filter((l) => !l.trim().startsWith('--'))
    .join('\n')
  const statements = code.split(';').filter((s) => s.trim()).length
  const kinds = new Map()
  for (const [, kind] of sql.matchAll(/^-- (\w+)$/gm)) kinds.set(kind, (kinds.get(kind) ?? 0) + 1)
  const breakdown = [...kinds].map(([k, n]) => `${n} ${k}`).join(', ')
  return `${statements} statement${statements === 1 ? '' : 's'}${breakdown ? `: ${breakdown}` : ''}`
}

function oneLine(text) {
  return String(text).trim().split('\n').slice(0, 12)
}
